(function() {
  'use strict';

  // State
  let state = {
    issues: [
      { Id: '1', Name: 'DQ-001', Object_Type__c: 'Lead', Field_Name__c: 'Email', Error_Message__c: 'Invalid email format', Priority__c: 'Critical', Status__c: 'Open', Detected_Date__c: '2024-01-15T10:30:00Z' },
      { Id: '2', Name: 'DQ-002', Object_Type__c: 'Account', Field_Name__c: 'Phone', Error_Message__c: 'Missing area code', Priority__c: 'High', Status__c: 'In Progress', Detected_Date__c: '2024-01-16T14:15:00Z' },
      { Id: '3', Name: 'DQ-003', Object_Type__c: 'Opportunity', Field_Name__c: 'Amount', Error_Message__c: 'Negative value detected', Priority__c: 'Critical', Status__c: 'Open', Detected_Date__c: '2024-01-17T09:00:00Z' },
      { Id: '4', Name: 'DQ-004', Object_Type__c: 'Lead', Field_Name__c: 'Company', Error_Message__c: 'Field is blank', Priority__c: 'Medium', Status__c: 'Fixed', Detected_Date__c: '2024-01-18T11:45:00Z' },
      { Id: '5', Name: 'DQ-005', Object_Type__c: 'Account', Field_Name__c: 'Industry', Error_Message__c: 'Invalid picklist value', Priority__c: 'Low', Status__c: 'Fixed', Detected_Date__c: '2024-01-19T15:20:00Z' },
      { Id: '6', Name: 'DQ-006', Object_Type__c: 'Opportunity', Field_Name__c: 'Close Date', Error_Message__c: 'Date in the past', Priority__c: 'High', Status__c: 'Open', Detected_Date__c: '2024-01-20T08:30:00Z' },
      { Id: '7', Name: 'DQ-007', Object_Type__c: 'Lead', Field_Name__c: 'Phone', Error_Message__c: 'Invalid format', Priority__c: 'Medium', Status__c: 'Fixed', Detected_Date__c: '2024-01-21T13:00:00Z' },
      { Id: '8', Name: 'DQ-008', Object_Type__c: 'Account', Field_Name__c: 'Website', Error_Message__c: 'Invalid URL', Priority__c: 'Low', Status__c: 'In Progress', Detected_Date__c: '2024-01-22T10:15:00Z' },
      { Id: '9', Name: 'DQ-009', Object_Type__c: 'Opportunity', Field_Name__c: 'Stage', Error_Message__c: 'Missing required field', Priority__c: 'Critical', Status__c: 'Open', Detected_Date__c: '2024-01-23T16:45:00Z' },
      { Id: '10', Name: 'DQ-010', Object_Type__c: 'Lead', Field_Name__c: 'Status', Error_Message__c: 'Invalid status value', Priority__c: 'Medium', Status__c: 'Fixed', Detected_Date__c: '2024-01-24T09:30:00Z' },
      { Id: '11', Name: 'DQ-011', Object_Type__c: 'Account', Field_Name__c: 'Billing Address', Error_Message__c: 'Incomplete address', Priority__c: 'Low', Status__c: 'Open', Detected_Date__c: '2024-01-25T14:20:00Z' },
      { Id: '12', Name: 'DQ-012', Object_Type__c: 'Opportunity', Field_Name__c: 'Probability', Error_Message__c: 'Value out of range', Priority__c: 'High', Status__c: 'Fixed', Detected_Date__c: '2024-01-26T11:00:00Z' }
    ],
    filteredIssues: [],
    selectedObjectType: '',
    selectedPriority: '',
    selectedStatus: '',
    loading: false
  };

  // Initialize
  function init() {
    state.filteredIssues = state.issues;
    updateStatistics();
    renderTable();
    attachEventListeners();
  }

  // Update statistics
  function updateStatistics() {
    const totalCount = state.filteredIssues.length;
    const criticalCount = state.filteredIssues.filter(issue => issue.Priority__c === 'Critical').length;
    const fixedCount = state.filteredIssues.filter(issue => issue.Status__c === 'Fixed').length;

    document.getElementById('totalIssuesCount').textContent = totalCount;
    document.getElementById('criticalCount').textContent = criticalCount;
    document.getElementById('fixedCount').textContent = fixedCount;
  }

  // Render table
  function renderTable() {
    const tbody = document.getElementById('issuesTableBody');
    const tableContainer = document.getElementById('issuesTableContainer');
    const noIssuesMessage = document.getElementById('noIssuesMessage');

    if (state.filteredIssues.length === 0) {
      tableContainer.style.display = 'none';
      noIssuesMessage.style.display = 'block';
      return;
    }

    tableContainer.style.display = 'block';
    noIssuesMessage.style.display = 'none';

    tbody.innerHTML = '';
    state.filteredIssues.forEach(issue => {
      const tr = document.createElement('tr');

      const formattedDate = new Date(issue.Detected_Date__c).toLocaleString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        hour12: true
      });

      tr.innerHTML = `
        <td>${issue.Name}</td>
        <td>${issue.Object_Type__c}</td>
        <td>${issue.Field_Name__c}</td>
        <td>${issue.Error_Message__c}</td>
        <td><span class="slds-badge">${issue.Priority__c}</span></td>
        <td><span class="slds-badge">${issue.Status__c}</span></td>
        <td>${formattedDate}</td>
      `;
      tbody.appendChild(tr);
    });
  }

  // Apply filters
  function applyFilters() {
    state.loading = true;
    showLoading(true);

    setTimeout(() => {
      state.filteredIssues = state.issues.filter(issue => {
        const objectTypeMatch = !state.selectedObjectType || issue.Object_Type__c === state.selectedObjectType;
        const priorityMatch = !state.selectedPriority || issue.Priority__c === state.selectedPriority;
        const statusMatch = !state.selectedStatus || issue.Status__c === state.selectedStatus;
        return objectTypeMatch && priorityMatch && statusMatch;
      });

      updateStatistics();
      renderTable();
      showLoading(false);
      state.loading = false;
      showToast('Filters applied successfully', 'success');
    }, 500);
  }

  // Clear filters
  function clearFilters() {
    state.selectedObjectType = '';
    state.selectedPriority = '';
    state.selectedStatus = '';

    document.getElementById('objectTypeCombo').value = '';
    document.getElementById('priorityCombo').value = '';
    document.getElementById('statusCombo').value = '';

    state.filteredIssues = state.issues;
    updateStatistics();
    renderTable();
    showToast('Filters cleared', 'success');
  }

  // Show loading spinner
  function showLoading(show) {
    const spinner = document.getElementById('loadingSpinner');
    const tableContainer = document.getElementById('issuesTableContainer');
    const noIssuesMessage = document.getElementById('noIssuesMessage');

    if (show) {
      spinner.style.display = 'block';
      tableContainer.style.display = 'none';
      noIssuesMessage.style.display = 'none';
    } else {
      spinner.style.display = 'none';
    }
  }

  // Show toast message
  function showToast(message, variant) {
    const toastContainer = document.getElementById('toastContainer');
    const toast = document.getElementById('toast');
    const toastMessage = document.getElementById('toastMessage');
    const toastVariantEl = document.getElementById('toastVariant');

    toastMessage.textContent = message;
    toastVariantEl.textContent = variant;

    toast.className = 'slds-notify slds-notify_toast';
    if (variant === 'success') {
      toast.classList.add('slds-theme_success');
    } else if (variant === 'error') {
      toast.classList.add('slds-theme_error');
    }

    toastContainer.style.display = 'block';

    setTimeout(() => {
      toastContainer.style.display = 'none';
    }, 3000);
  }

  // Attach event listeners
  function attachEventListeners() {
    document.getElementById('applyFiltersBtn').addEventListener('click', applyFilters);
    document.getElementById('clearFiltersBtn').addEventListener('click', clearFilters);

    // Simple combobox interaction (read-only for preview)
    const objectTypeCombo = document.getElementById('objectTypeCombo');
    const priorityCombo = document.getElementById('priorityCombo');
    const statusCombo = document.getElementById('statusCombo');

    objectTypeCombo.addEventListener('focus', function() {
      this.placeholder = 'Lead, Account, Opportunity';
    });
    objectTypeCombo.addEventListener('blur', function() {
      if (this.value) {
        state.selectedObjectType = this.value;
      }
      this.placeholder = 'All Objects';
    });

    priorityCombo.addEventListener('focus', function() {
      this.placeholder = 'Critical, High, Medium, Low';
    });
    priorityCombo.addEventListener('blur', function() {
      if (this.value) {
        state.selectedPriority = this.value;
      }
      this.placeholder = 'All Priorities';
    });

    statusCombo.addEventListener('focus', function() {
      this.placeholder = 'Open, In Progress, Fixed';
    });
    statusCombo.addEventListener('blur', function() {
      if (this.value) {
        state.selectedStatus = this.value;
      }
      this.placeholder = 'All Statuses';
    });
  }

  // Initialize on load
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

